static class LanguageCatalog {
 public static readonly string[] Codes={"ru","en","de","fr","it","uk","es"};
 public static readonly string[] Names={"Русский","English","Deutsch","Français","Italiano","Українська","Español"};
 public static string DocumentLanguage="ru";
 static Dictionary<string,string[]> phrases=new Dictionary<string,string[]>(StringComparer.Ordinal);
 static void Add(string ru,string en,string de,string fr,string it,string uk,string es){phrases.Add(ru,new[]{ru,en,de,fr,it,uk,es});}
 public static bool Valid(string code){return Codes.Contains(code);}
 public static string T(string text,string code){if(text==null)return "";int i=Array.IndexOf(Codes,code);if(i<0)throw new ArgumentException("Unsupported language: "+code);string[] values;if(phrases.TryGetValue(text,out values))return values[i];return text;}
 public static string[] ScheduleHeaders(string code){return new[]{"Имя списка вырезов","Материал","Количество","Ширина, мм","Высота, мм","Направление реза","Угол 1","Длина, мм","Угол 2","Направление реза"}.Select(x=>T(x,code)).ToArray();}
 public static string[] Keys {get{return phrases.Keys.ToArray();}}
 public static void WriteDeliveryNote(string root,string code,string kind){
  string[] lines={"PartCraft — "+T("Документация SolidWorks",code),"",T("Модель и числовые значения сохранены без перевода.",code),"",T("Где находятся файлы",code),"DXF — "+T("Рабочие DXF",code),"Profile — "+T("Чертёж и PDF профилей",code),"DXF/Faces — "+T("DXF выбранных граней",code),"",T("Проверьте масштаб, контуры и назначение операций в вашей CAM-системе.",code),"",T("Язык документации",code)+": "+Names[Array.IndexOf(Codes,code)],"Module: "+kind};
  File.WriteAllLines(Path.Combine(root,"READ_ME_"+kind+"_"+code+".txt"),lines,new UTF8Encoding(true));
 }
